const IC_trace=(F,key)=>{const it=F.items.find(q=>q[1].startsWith('<polyline')&&q[1].includes(key));return it[1].match(/points="([^"]+)"/)[1].trim().split(/\s+/).map(p=>p.split(',').map(Number))};
/* book Figure 3.1.1 axes: x 80..690 is θ −40°..60°, y 370 is 0 bar and 58.2 px per 10 bar */
const IC_FIRE=IC_trace(IC_F31,'stroke:var(--accent);stroke-width:3').map(([x,y])=>[-40+(x-80)/6.1,(370-y)/5.82]);
const IC_MOTOR=IC_trace(IC_F31,'stroke-dasharray:6 4').map(([x,y])=>[-40+(x-80)/6.1,(370-y)/5.82]);
/* book Figure 3.2.1 axes: x 80..690 is θ −20°..50°, y 360 is 0 bar and 49.2 px per 10 bar; the normal burn is the accent trace */
const IC_NORM=IC_trace(IC_F32A,'stroke:var(--accent);stroke-width:3').map(([x,y])=>[-20+(x-80)/(610/70),(360-y)/4.92]);
/* map [θ, p] into a box */
const IC_map=(D,x0,x1,y0,y1,t0,t1,p1)=>D.map(([t,p])=>[x0+(t-t0)*(x1-x0)/(t1-t0),y1-p*(y1-y0)/p1]);
/* a mass-fraction-burned S-curve (Wiebe form, a = 5, m = 2), computed point by point */
const IC_WIEBE=Array.from({length:61},(_,i)=>{const z=i/60;return [z,1-Math.exp(-5*z**3)]});
const IC_WRATE=Array.from({length:61},(_,i)=>{const z=i/60;return [z,15*z*z*Math.exp(-5*z**3)]});

