 +`<path d="M140,80 Q180,180 140,290 L40,290 Q80,180 40,80 Z" fill="${ORG}" fill-opacity=".35"/><path d="M140,80 Q180,180 140,290" fill="none" stroke="${ORG}" stroke-width="8"/>`+IC_T(90,320,'burnt',{fs:22,a:'middle',fill:IC_GREY})+``
