function EXTRA(R,ICON){
 /* hook: two timing dials, the spark angle before TDC shaded */
 const dial=(x,y,deg,rpm,col)=>{const r=56,cx=70,cy=80,a=-Math.PI/2-deg*Math.PI/180;
  return `<g transform="translate(${x-190} ${y-80})">${IC_box(0,0,380,160,{fill:'#FFFFFF',st:col,sw:3,r:18})}<circle cx="${cx}" cy="${cy}" r="${r}" fill="#F1F3F5" stroke="#343A40" stroke-width="4"/>
  <path d="M${cx},${cy} L${cx},${cy-r} A${r},${r} 0 0 0 ${(cx+r*Math.cos(a)).toFixed(1)},${(cy+r*Math.sin(a)).toFixed(1)} Z" fill="${col}" fill-opacity=".45"/>
  ${IC_L(cx,cy+r,cx,cy-r-8,'#343A40',3)}${IC_L(cx,cy,cx+(r+8)*Math.cos(a),cy+(r+8)*Math.sin(a),col,4)}${IC_spark(cx+(r+16)*Math.cos(a),cy+(r+16)*Math.sin(a)+4,.55,col)}
  ${IC_T(cx+10,cy-r+2,'TDC',{fs:20,fw:800,a:'start',fill:IC_GREY})}
  ${IC_T(150,62,rpm,{fs:26,fw:800,fill:col})}${IC_T(150,100,`spark ${deg}° bTDC`,{fs:24,fw:700})}${IC_T(150,132,'crank turns clockwise',{fs:20,fill:IC_GREY})}</g>`};
 ICON.hkT28=(x,y)=>dial(x,y,28,'3000 rev/min',BLU);
 ICON.hkT37=(x,y)=>dial(x,y,37,'4500 rev/min',ORG);
 /* the three burns of Figure 3.2.1, one highlighted (book traces; x 80..690 = −20°..50°, y 360 = 0 bar) */
 const burn=(key,col)=>{const all=['stroke:var(--live)','stroke:var(--accent)','stroke:var(--next)'].map(k=>IC_trace(IC_F32A,k));const M=([x,y])=>[-125+(x-80)*250/610,58-(360-y)*116/300];
  const mine=IC_trace(IC_F32A,key).map(M),pk=mine.reduce((q,r)=>r[1]<q[1]?r:q);
  return IC_L(-125,58,125,58,'#343A40',3)+IC_L(-125,-58,-125,58,'#343A40',3)+all.map(p=>IC_poly(p.map(M),'#CED4DA',2.5)).join('')+IC_poly(mine,col,5)+`<circle cx="${pk[0].toFixed(1)}" cy="${pk[1].toFixed(1)}" r="8" fill="${col}"/>`};
 ICON.icBurnFast=(x,y)=>`<g transform="translate(${x} ${y})">${burn('stroke:var(--live)',ORG)}</g>`;
 ICON.icBurnNorm=(x,y)=>`<g transform="translate(${x} ${y})">${burn('stroke:var(--accent)',BLU)}</g>`;
 ICON.icBurnSlow=(x,y)=>`<g transform="translate(${x} ${y})">${burn('stroke:var(--next)',GRN)}</g>`;
 /* recap pictures, drawn from the book's computed traces */
 ICON.icStages=(x,y)=>{const X=t=>20+(t+40)*4,Y=p=>270-p*4.4,pts=IC_FIRE.map(([t,p])=>[X(t),Y(p)]),mo=IC_MOTOR.map(([t,p])=>[X(t),Y(p)]);
  return `<g transform="translate(${x-210} ${y-165})"><rect x="${X(-28)}" y="20" width="${X(-10)-X(-28)}" height="250" fill="${BLU}" fill-opacity=".18"/><rect x="${X(-10)}" y="20" width="${X(15.6)-X(-10)}" height="250" fill="${ORG}" fill-opacity=".2"/><rect x="${X(15.6)}" y="20" width="${X(60)-X(15.6)}" height="250" fill="${GRN}" fill-opacity=".16"/>
  ${IC_L(20,270,420,270,'#343A40',3)}${IC_L(20,20,20,270,'#343A40',3)}${IC_poly(mo,IC_GREY,2,'stroke-dasharray="6 5"')}${IC_poly(pts,BLU,4)}
  ${[[-28,'A',BLU],[-10,'B',ORG],[15.6,'C',GRN]].map(([t,l,col])=>{const p=IC_FIRE.reduce((q,r)=>Math.abs(r[0]-t)<Math.abs(q[0]-t)?r:q)[1];return `<circle cx="${X(t)}" cy="${Y(p)}" r="9" fill="${col}"/>`+IC_T(X(t)+(l==='C'?16:-4),Y(p)-16,l,{fs:26,fw:800,a:l==='C'?'start':'end',fill:col})}).join('')}
  ${IC_T(X(-19),302,'I',{fs:24,fw:800,a:'middle',fill:BLU})}${IC_T(X(2.8),302,'II',{fs:24,fw:800,a:'middle',fill:ORG})}${IC_T(X(38),302,'III',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`};
 ICON.icAdvance=(x,y)=>{const X=t=>380+9*t;
  return `<g transform="translate(${x-236} ${y-198}) scale(1.35)">${IC_T(20,40,'3000 rev/min',{fs:24,fw:800,fill:BLU})}<rect x="${X(-28)}" y="56" width="${X(-10)-X(-28)}" height="50" rx="6" fill="${BLU}"/>${IC_T((X(-28)+X(-10))/2,90,'18°',{fs:26,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${IC_T(20,156,'4500 rev/min',{fs:24,fw:800,fill:ORG})}<rect x="${X(-37)}" y="172" width="${X(-10)-X(-37)}" height="50" rx="6" fill="${ORG}"/>${IC_T((X(-37)+X(-10))/2,206,'27°',{fs:26,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${IC_L(X(-10),30,X(-10),250,GRN,4,'stroke-dasharray="8 6"')}${IC_T(X(-10)+10,140,'B',{fs:26,fw:800,fill:GRN})}
  ${IC_T(210,290,'same 1.0 ms of lag',{fs:24,fw:800,a:'middle',fill:IC_GREY})}</g>`};
 ICON.icSlope=(x,y)=>{const X=t=>30+(t+20)*5.6,Y=p=>280-p*4.3,pts=IC_NORM.map(([t,p])=>[X(t),Y(p)]),near=t=>IC_NORM.reduce((q,r)=>Math.abs(r[0]-t)<Math.abs(q[0]-t)?r:q)[1];
  return `<g transform="translate(${x-210} ${y-165})">${IC_L(30,280,422,280,'#343A40',3)}${IC_L(30,20,30,280,'#343A40',3)}${IC_poly(pts,BLU,4)}
  ${IC_L(X(0),Y(24.9),X(10),Y(45.4),GRN,5,'stroke-dasharray="8 5"')}<circle cx="${X(0)}" cy="${Y(24.9)}" r="8" fill="${GRN}"/><circle cx="${X(10)}" cy="${Y(45.4)}" r="8" fill="${GRN}"/>
  ${IC_T(236,236,'2.05 bar/°CA',{fs:24,fw:800,fill:GRN})}${IC_T(236,264,'average slope',{fs:22,fill:IC_GREY})}${IC_T(X(0),306,'TDC',{fs:22,fw:700,a:'middle',fill:IC_GREY})}</g>`};
}
